"""Auto-generated self-audit: independent recomputations of engine output (written to sanity_checks.md)."""
from __future__ import annotations

import numpy as np
import pandas as pd

from . import config, metrics


def recompute_trade_pnl(panel: dict, screen: pd.DataFrame, pair: dict, trade: pd.Series) -> dict:
    """Recompute one closed trade's net P&L from raw prices, independent of the engine loop."""
    s = screen.set_index("ticker")
    a, b = pair["leg_a"], pair["leg_b"]
    sess = panel["adjclose"].index
    ie = int(sess.get_loc(pd.Timestamp(trade["entry_date"])))
    ix = int(sess.get_loc(pd.Timestamp(trade["exit_date"])))
    ratio = float(trade["beta"])
    sign = 1.0 if trade["side"].startswith("long A") else -1.0
    w = {a: sign / (1.0 + ratio), b: -sign * ratio / (1.0 + ratio)}
    total = 0.0
    parts = {}
    for t in (a, b):
        slip = float(s.loc[t, "slippage_bps"]) / 1e4
        rate = float(s.loc[t, "borrow_rate"]) / config.BORROW_DAYS
        ao, ro, ac = panel["adjopen"][t].to_numpy(), panel["open"][t].to_numpy(), panel["adjclose"][t].to_numpy()
        shares = w[t] * float(trade["entry_equity"]) / ao[ie]
        fill_in = ao[ie] * (1 + slip) if shares > 0 else ao[ie] * (1 - slip)
        fill_out = ao[ix] * (1 - slip) if shares > 0 else ao[ix] * (1 + slip)
        comm_in = max(config.COMMISSION_MIN, config.COMMISSION_PER_SHARE * abs(shares) * ao[ie] / ro[ie])
        comm_out = max(config.COMMISSION_MIN, config.COMMISSION_PER_SHARE * abs(shares) * ao[ix] / ro[ix])
        borrow = 0.0
        if shares < 0:
            borrow = float(np.sum(-shares * ac[ie:ix] * rate))      # held at the close of sessions ie .. ix-1
        pnl = shares * (fill_out - fill_in) - comm_in - comm_out - borrow
        parts[t] = {"shares": shares, "fill_in": fill_in, "fill_out": fill_out, "pnl": pnl, "borrow": borrow}
        total += pnl
    return {"recomputed": total, "engine": float(trade["net_pnl"]), "parts": parts}


def build_sanity_report(panel, screen, pool, trials_dir, spy_ret, gates, wlog=None) -> str:
    L = ["# Sanity checks (auto-generated by `backtest.audit`)", ""]
    s, e = config.REGIMES["full"]
    r = spy_ret.loc[s:e].dropna().to_numpy()
    L += ["## SPY buy-and-hold over the full OOS span",
          f"- span {s} -> {e}, {len(r)} daily returns (adjusted close, total return)",
          f"- CAGR {metrics.cagr(r):.2%}, Sharpe {metrics.sharpe(r):.2f}, max drawdown {metrics.max_drawdown(r):.1%}",
          "- Expected ballpark for this span: roughly 12-14% CAGR for the S&P 500 total return.", ""]
    raw = panel["close"]["SPY"].loc[s:e].dropna()
    price_cagr = float((raw.iloc[-1] / raw.iloc[0]) ** (252.0 / (len(raw) - 1)) - 1.0)
    L += [f"- price-only (unadjusted-for-dividends) SPY CAGR over the same span: {price_cagr:.2%} "
          f"(close {raw.iloc[0]:.2f} -> {raw.iloc[-1]:.2f}); the adjusted-close total-return CAGR above is higher by "
          f"{metrics.cagr(r) - price_cagr:.2%} per year, which is the dividend contribution",
          ""]
    for reg in config.REGIME_ORDER:
        rs, re_ = config.REGIMES[reg]
        x = spy_ret.loc[rs:re_].dropna().to_numpy()
        L.append(f"- SPY {reg}: CAGR {metrics.cagr(x):.2%}, Sharpe {metrics.sharpe(x):.2f}, maxDD {metrics.max_drawdown(x):.1%}")
    L.append("")
    # trade P&L recomputation for a few runs
    L += ["## Trade P&L recomputed from raw prices (independent of the engine loop)", ""]
    checked = 0
    worst = 0.0
    n_trades = 0
    rows = []
    gi = gates[gates["rule"].isin(["coint_ols", "rotation", "leadlag", "coint_kalman"])]
    for rule in ("coint_ols", "coint_kalman", "rotation", "leadlag"):
        sub = gi[gi["rule"] == rule]
        for pid in sub["pair_id"].head(4):
            k = f"{pid}__{rule}"
            tp = trials_dir / f"{k}_trades.csv"
            if not tp.exists():
                continue
            tr = pd.read_csv(tp, parse_dates=["entry_date", "exit_date"])
            tr = tr[~tr["open_at_end"]]
            pair = pool[pool["pair_id"] == pid].iloc[0].to_dict()
            for _, t in tr.head(6).iterrows():
                res = recompute_trade_pnl(panel, screen, pair, t)
                err = abs(res["recomputed"] - res["engine"])
                worst = max(worst, err)
                n_trades += 1
                if checked < 8:
                    rows.append((pid, rule, str(t["entry_date"].date()), str(t["exit_date"].date()), t["side"],
                                 res["engine"], res["recomputed"]))
                    checked += 1
    L.append(f"- {n_trades} closed trades recomputed; worst absolute difference vs engine: {worst:.6f} dollars")
    L.append("")
    L.append("| pair | rule | entry | exit | side | engine net P&L | recomputed |")
    L.append("|---|---|---|---|---|---|---|")
    for pid, rule, e0, e1, side, pe, pr in rows:
        L.append(f"| {pid} | {rule} | {e0} | {e1} | {side} | {pe:.2f} | {pr:.2f} |")
    L.append("")
    # equity identity
    L += ["## Equity identity (sum of trade P&L == final equity - start capital)", ""]
    worst_id = 0.0
    n_id = 0
    for _, g in gates.iterrows():
        k = f"{g['pair_id']}__{g['rule']}"
        d = pd.read_csv(trials_dir / f"{k}.csv.gz", index_col=0, parse_dates=True)
        t = pd.read_csv(trials_dir / f"{k}_trades.csv")
        diff = abs(float(t["net_pnl"].sum()) - (float(d["equity"].iloc[-1]) - config.START_CAPITAL))
        worst_id = max(worst_id, diff)
        n_id += 1
    L.append(f"- checked on all {n_id} trials; worst absolute difference: {worst_id:.6f} dollars")
    L.append("")
    if wlog is not None and len(wlog):
        L += ["## Behavioural observations (computed)", ""]
        per = gates.groupby("rule").agg(trials=("pair_id", "size"), median_round_trips=("full_round_trips", "median"),
                                         median_avg_hold_days=("full_avg_hold_days", "median"),
                                         median_exposure=("full_exposure", "median"),
                                         median_cost_drag_ann=("cost_drag_ann_full", "median"),
                                         median_full_sharpe=("full_sharpe", "median")).reset_index()
        v = wlog.groupby("rule")["valid"].mean().rename("share_windows_with_entries_allowed").reset_index()
        per = per.merge(v, on="rule")
        L.append("| rule | trials | median round trips | median avg hold (days) | median exposure | median cost drag (ann.) | "
                 "median full Sharpe | share of windows allowing entries |")
        L.append("|---|---|---|---|---|---|---|---|")
        for r in per.itertuples():
            L.append(f"| {r.rule} | {r.trials} | {r.median_round_trips:.0f} | {r.median_avg_hold_days:.1f} | "
                     f"{r.median_exposure:.2f} | {r.median_cost_drag_ann:.3f} | {r.median_full_sharpe:.2f} | "
                     f"{r.share_windows_with_entries_allowed:.2f} |")
        L.append("")
        for rule in ("leadlag", "leadlag_rev"):
            ll = wlog[wlog["rule"] == rule]
            if len(ll):
                vc = ll["k_star"].dropna().astype(int).value_counts().sort_index()
                L.append(f"- {rule}: chosen lag k* by window = " + ", ".join(f"{k}:{n}" for k, n in vc.items())
                         + f"; windows rejected: " + "; ".join(f"{k} x{n}" for k, n in ll.loc[~ll['valid'], 'reason'].value_counts().items()))
        co = wlog[wlog["rule"] == "coint_ols"]
        L.append("- coint_ols windows with beta out of range: "
                 f"{int((co['reason'] == 'beta out of range').sum())} of {len(co)}")
        # series whose first training windows reach back before the operating company existed (PR = Silver Run SPAC)
        pr = wlog[(wlog["pair_id"].str.contains("PR")) & (wlog["rule"] == "coint_ols") & (wlog["fit_start"] < "2016-10-11")]
        if len(pr):
            L.append("- FANG_PR: training windows " + ", ".join(str(int(k)) for k in pr["k"])
                     + " start before 2016-10-11 (Centennial/Silver Run merger); their training samples include the "
                       "pre-merger SPAC series (see IMPLEMENTATION_NOTES.md)")
        L.append("")
    return "\n".join(L)
